# Converts GravePain's SynthFactoryPresets.cs (the author's own presets) and SynthMacros.cs into C++ tables for
# src/core/GpSynthBank.cpp. Writes the generated file to argv[3].
import re, sys

presets_cs, macros_cs, out_path = sys.argv[1], sys.argv[2], sys.argv[3]
src = open(presets_cs, encoding='utf-8').read()

enum_values = {
    'SynthWave': ['Sine', 'Triangle', 'Saw', 'Square', 'Wavetable', 'SawDown', 'ThreeStep', 'FourStep', 'EightStep', 'ThreePyramid', 'FivePyramid', 'NinePyramid'],
    'SynthFilterMode': ['LowPass', 'BandPass', 'HighPass', 'Notch', 'Peak', 'LowPass24', 'Blend', 'LowShelf', 'HighShelf'],
    'SynthLfoWave': ['Sine', 'Triangle', 'Saw', 'Square', 'Random'],
    'SynthVoiceMode': ['Poly', 'Mono', 'Legato'],
    'SynthPitchCurve': ['Fall', 'Build'],
    'SynthDivision': ['Whole', 'Half', 'Quarter', 'DottedEighth', 'Eighth', 'EighthTriplet', 'Sixteenth', 'SixteenthTriplet', 'ThirtySecond'],
}
# GravePain's wavetable banks are not shipped (origin not recorded): the nearest of LYNX's own generated banks
table_index = {'BasicShapes': 0, 'PWM': 1, 'Harmonic': 2, 'Digital': 2, 'Formant': 0}
dropped_fields = {'arpOn', 'arpGate', 'arpDivision', 'arpOctaves', 'arpMode', 'arpLatch'}  # LYNX: the channel's arpeggiator

def value_of(field, raw):
    raw = raw.strip()
    m = re.match(r'(Synth\w+)\.(\w+)$', raw)
    if m:
        return float(enum_values[m.group(1)].index(m.group(2)))
    if raw in ('true', 'false'):
        return 1.0 if raw == 'true' else 0.0
    if raw.startswith('"'):
        name = raw.strip('"')
        if field in ('tableA', 'tableB'):
            return float(table_index[name])
        return None
    return float(raw.rstrip('fF'))

entries, skipped = [], []
pattern = re.compile(r'Add\("([^"]+)",\s*"([^"]+)",\s*Tags\(([^)]*)\),\s*p\s*=>\s*\{(.*?)\}(?:,\s*([-\d]+))?(?:,\s*([\d.]+)f?)?\);', re.S)
for m in pattern.finditer(src):
    name, kind, tags, body, note, hold = m.groups()
    tags = re.findall(r'"([^"]+)"', tags)
    values, why = [], None
    for field, raw in re.findall(r'p\.(\w+)\s*=\s*([^;]+);', body):
        if field in dropped_fields:
            continue
        if field in ('sampleSource',):
            why = 'plays FL Keys samples, which are not shipped'
            break
        v = value_of(field, raw)
        if v is None:
            why = 'unreadable ' + field
            break
        values.append((field, v))
    if why:
        skipped.append((name, why))
        continue
    entries.append((name, kind, tags, values, int(note) if note else 60, float(hold) if hold else 0.0))

msrc = re.sub(r'//[^\n]*', '', open(macros_cs, encoding='utf-8').read())  # (comments between dials)
macro_sets = []
lead = re.search(r'static readonly SynthMacro\[\] Lead =\s*\{(.*?)\};', msrc, re.S).group(1)
def parse_set(text):
    out = []
    for mm in re.finditer(r'M\("([^"]+)",(.*?)\)\),?\s*(?=M\(|$)', text.strip() + ' ', re.S):
        parts = re.findall(r'P\("(\w+)",\s*([-\d.]+)f?,\s*([-\d.]+)f?(?:,\s*(true))?\)', mm.group(2) + ')')
        out.append((mm.group(1), parts))
    return out
macro_sets.append(('Lead', parse_set(lead)))
for mm in re.finditer(r'\{ "([^"]+)", new\[\]\s*\{(.*?)\}\s*\}', msrc, re.S):
    macro_sets.append((mm.group(1), parse_set(mm.group(2))))

def f(v):
    s = repr(float(v))
    return s + 'f'

lines = ['// Generated by tools/gravepain/convert_presets.py from GravePain\'s SynthFactoryPresets.cs and SynthMacros.cs',
         '// (the author\'s own sounds and dials). Do not edit by hand: change the generator or the sources.', '']
lines.append('const std::vector<FactoryPreset>& factoryPresets()\n{\n    static const std::vector<FactoryPreset> list {')
for name, kind, tags, values, note, hold in entries:
    vals = ', '.join('{ %s, %s }' % (fld, f(v)) for fld, v in values)
    tg = ', '.join('"%s"' % t for t in tags)
    lines.append('        { "%s", "%s", { %s }, %d, %s, { %s } },' % (name, kind, tg, note, f(hold), vals))
lines.append('    };\n    return list;\n}\n')
lines.append('const std::vector<MacroSet>& macroSets()\n{\n    static const std::vector<MacroSet> list {')
for kind, macros in macro_sets:
    ms = []
    for mname, parts in macros:
        ps = ', '.join('{ %s, %s, %s, %s }' % (p[0], f(p[1]), f(p[2]), 'true' if p[3] else 'false') for p in parts if p[0] not in dropped_fields)
        if ps:
            ms.append('{ "%s", { %s } }' % (mname, ps))
    lines.append('        { "%s", { %s } },' % (kind, ', '.join(ms)))
lines.append('    };\n    return list;\n}')
open(out_path, 'w', encoding='utf-8', newline='\n').write('\n'.join(lines) + '\n')
print(len(entries), 'presets,', len(macro_sets), 'macro sets; skipped:', skipped)
